import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;

/**
 * Plain unit test: Mockito for mocking, AssertJ for assertions.
 */
@ExtendWith(MockitoExtension.class)
class GreetingServiceTest {

    @Mock
    private GreetingRepository repository;

    @InjectMocks
    private GreetingService service;

    @Test
    void greetsWithNameResolvedFromRepository() {
        given(this.repository.findName(1L)).willReturn("World");

        String greeting = this.service.greet(1L);

        assertThat(greeting).isEqualTo("Hello, World!");
        verify(this.repository).findName(1L);
    }

}

package com.example.demo.greeting;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

import static org.mockito.BDDMockito.given;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * Web slice test: loads only the MVC layer and replaces the service with a mock.
 */
@WebMvcTest(GreetingController.class)
class GreetingControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private GreetingService service;

    @Test
    void returnsGreetingForId() throws Exception {
        given(this.service.greet(1L)).willReturn("Hello, World!");

        this.mockMvc.perform(get("/greetings/1"))
                .andExpect(status().isOk())
                .andExpect(content().string("Hello, World!"));
    }

}
